//! noevia#1318: native `POST /api/v1/models/delete` through the real router.
//!
//! On Linux every case of `fixtures/model-delete-python.v1.json` (the actual services Python,
//! regenerated by CI from the pinned ref) runs through the router, FastAPI's `dict` body rules
//! and the kernel-contained opener: answers, the tree left behind and the container listings must
//! match. Elsewhere that opener refuses by design (503, nothing deleted), which is asserted
//! instead; the lib tests run the same cases on every platform. Docker and mountinfo are fakes
//! and every name is synthetic.
#![cfg(feature = "native-model-delete")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{body::Body, http::Request};
use http_body_util::BodyExt;
use noevia_model_manager::{
    model_delete::{Config, ModelDelete, Running},
    Container, DockerRead, Redactor, StateData,
};
use serde_json::Value;
use std::{
    future::Future,
    path::{Path, PathBuf},
    pin::Pin,
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc,
    },
};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";
const PATH: &str = "/api/v1/models/delete";

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;

struct FakeDocker {
    spec: Value,
    lists: AtomicUsize,
}

impl DockerRead for FakeDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
    fn running_containers(&self) -> Job<'_, Option<Vec<Running>>> {
        if !self.spec.is_null() {
            self.lists.fetch_add(1, Ordering::SeqCst);
        }
        let spec = self.spec.clone();
        Box::pin(async move {
            match spec {
                Value::Null => Ok(None),
                Value::String(s) if s == "fail" => Err("APIError"),
                Value::Array(list) => Ok(Some(list.iter().map(running).collect())),
                other => panic!("{other}"),
            }
        })
    }
}

fn strings(v: &Value) -> Vec<String> {
    match v {
        Value::Null => Vec::new(),
        Value::String(s) => vec![s.clone()],
        Value::Array(items) => items
            .iter()
            .map(|i| i.as_str().unwrap().to_owned())
            .collect(),
        other => panic!("{other}"),
    }
}

fn running(spec: &Value) -> Running {
    Running {
        name: spec["name"].as_str().unwrap().to_owned(),
        id: spec["id"].as_str().unwrap().to_owned(),
        entrypoint: strings(&spec["entrypoint"]),
        cmd: strings(&spec["cmd"]),
        args: strings(&spec["args"]),
        env: strings(&spec["env"]),
        mounts: spec["mounts"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| {
                (
                    m["Destination"].as_str().unwrap_or_default().to_owned(),
                    m["Source"].as_str().unwrap_or_default().to_owned(),
                )
            })
            .collect(),
    }
}

fn state(
    delete: Option<ModelDelete>,
    docker: Arc<FakeDocker>,
    legacy_base: &str,
) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        model_updates: None,
        model_detail: None,
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker,
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
        #[cfg(feature = "native-bench-runs")]
        bench_runs: None,
        #[cfg(feature = "native-section-writes")]
        section_writes: None,
        #[cfg(feature = "native-settings-write")]
        settings_write: None,
        #[cfg(feature = "native-benchmark-overview")]
        benchmark_overview: None,
        #[cfg(feature = "native-check-updates")]
        check_updates: None,
        #[cfg(feature = "native-downloads")]
        downloads: None,
        model_delete: delete.map(Arc::new),
        #[cfg(feature = "native-benchmark-runner")]
        bench_runner: None,
        #[cfg(feature = "native-backend-control")]
        backends: None,
    })
}

async fn post(
    state: Arc<StateData>,
    body: &str,
    content_type: Option<&str>,
    token: bool,
) -> (u16, Option<String>, String) {
    let mut request = Request::builder().method("POST").uri(PATH);
    if token {
        request = request.header("x-model-loader-token", TOKEN);
    }
    if let Some(kind) = content_type {
        request = request.header("content-type", kind);
    }
    let response = noevia_model_manager::router(state)
        .oneshot(request.body(Body::from(body.to_owned())).unwrap())
        .await
        .unwrap();
    let status = response.status().as_u16();
    let kind = response
        .headers()
        .get("content-type")
        .map(|v| v.to_str().unwrap().to_owned());
    let bytes = response.into_body().collect().await.unwrap().to_bytes();
    (status, kind, String::from_utf8(bytes.to_vec()).unwrap())
}

fn config(models: &Path, mountinfo: &Path, case: &Value) -> Config {
    let env = &case["env"];
    let text = |key: &str| env[key].as_str().unwrap_or_default().to_owned();
    Config {
        models: models.to_str().unwrap().to_owned(),
        ini: models.join("models.ini"),
        host_path: text("MODELS_HOST_PATH"),
        targets: text("MODEL_DOWNLOAD_TARGETS"),
        mountinfo: mountinfo.to_owned(),
        hostname: text("HOSTNAME"),
        embed: env["NOEVIA_EMBED_SERVICE_GUARDED"]
            .as_str()
            .filter(|v| *v == "1")
            .map(|_| {
                (
                    text("NOEVIA_EMBED_SERVICE_CONTAINER"),
                    text("NOEVIA_EMBED_SERVICE_URL"),
                )
            }),
    }
}

fn synthetic_tree(root: &Path) -> PathBuf {
    let models = root.join("models");
    std::fs::create_dir_all(models.join("sub")).unwrap();
    std::fs::write(models.join("x.gguf"), b"0123456789").unwrap();
    std::fs::write(models.join("sub/s.gguf"), b"01234").unwrap();
    models
}

#[tokio::test]
async fn the_token_is_checked_first() {
    let dir = tempfile::tempdir().unwrap();
    let models = synthetic_tree(dir.path());
    let docker = Arc::new(FakeDocker {
        spec: Value::Null,
        lists: AtomicUsize::new(0),
    });
    let delete = ModelDelete::new(
        config(&models, &dir.path().join("none"), &Value::Null),
        docker.clone(),
    );
    let (status, _, _) = post(
        state(Some(delete), docker, "http://127.0.0.1:9"),
        r#"{"models":["x.gguf"]}"#,
        Some("application/json"),
        false,
    )
    .await;
    assert_eq!(status, 401);
    assert!(models.join("x.gguf").exists());
}

/// With the selector off the route is the child's (here: no child, the forward's 502).
#[tokio::test]
async fn selector_off_forwards() {
    let gone = {
        let l = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        format!("http://{}", l.local_addr().unwrap())
    };
    let dir = tempfile::tempdir().unwrap();
    let models = synthetic_tree(dir.path());
    let docker = Arc::new(FakeDocker {
        spec: Value::Null,
        lists: AtomicUsize::new(0),
    });
    let (status, _, _) = post(
        state(None, docker, &gone),
        r#"{"models":["x.gguf"]}"#,
        Some("application/json"),
        true,
    )
    .await;
    assert_eq!(status, 502);
    assert!(models.join("x.gguf").exists());
}

/// The kernel-contained opener exists only on Linux: elsewhere the route refuses, deleting nothing.
#[cfg(not(target_os = "linux"))]
#[tokio::test]
async fn other_platforms_refuse() {
    let dir = tempfile::tempdir().unwrap();
    let models = synthetic_tree(dir.path());
    let docker = Arc::new(FakeDocker {
        spec: Value::Null,
        lists: AtomicUsize::new(0),
    });
    let delete = ModelDelete::new(
        config(&models, &dir.path().join("none"), &Value::Null),
        docker.clone(),
    );
    let (status, _, body) = post(
        state(Some(delete), docker, "http://127.0.0.1:9"),
        r#"{"models":["x.gguf"]}"#,
        Some("application/json"),
        true,
    )
    .await;
    assert_eq!(
        (status, body.as_str()),
        (503, r#"{"detail":"Native model delete is unavailable"}"#)
    );
    assert!(models.join("x.gguf").exists());
}

#[cfg(target_os = "linux")]
fn build(root: &Path, case: &Value) -> PathBuf {
    let models = root.join("models");
    match case["models"].as_str() {
        Some("file") => std::fs::write(&models, b"").unwrap(),
        Some("missing") => {}
        _ => std::fs::create_dir(&models).unwrap(),
    }
    for f in case["files"].as_array().into_iter().flatten() {
        let path = models.join(f["name"].as_str().unwrap());
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::File::create(&path)
            .unwrap()
            .set_len(f["size"].as_u64().unwrap())
            .unwrap();
    }
    for link in case["links"].as_array().into_iter().flatten() {
        let path = models.join(link[0].as_str().unwrap());
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::os::unix::fs::symlink(link[1].as_str().unwrap(), &path).unwrap();
    }
    if let Some(text) = case["ini"].as_str() {
        std::fs::write(models.join("models.ini"), text).unwrap();
    }
    models
}

#[cfg(target_os = "linux")]
fn tree(root: &Path) -> Value {
    fn walk(root: &Path, dir: &Path, out: &mut Vec<Value>) {
        let mut names: Vec<_> = std::fs::read_dir(dir)
            .unwrap()
            .map(|e| e.unwrap().file_name())
            .collect();
        names.sort();
        for name in names {
            let path = dir.join(&name);
            let rel = path
                .strip_prefix(root)
                .unwrap()
                .to_str()
                .unwrap()
                .to_owned();
            let meta = std::fs::symlink_metadata(&path).unwrap();
            if meta.file_type().is_symlink() {
                let target = std::fs::read_link(&path).unwrap();
                out.push(serde_json::json!([rel, "link", target.to_str().unwrap()]));
            } else if meta.is_dir() {
                out.push(serde_json::json!([rel, "dir", null]));
                walk(root, &path, out);
            } else {
                out.push(serde_json::json!([rel, "file", meta.len()]));
            }
        }
    }
    let mut out = Vec::new();
    walk(root, root, &mut out);
    out.sort_by_key(|v| v.to_string());
    Value::Array(out)
}

#[cfg(target_os = "linux")]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn actual_python_differential_through_the_router() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/model-delete-python.v1.json")).unwrap();
    let info = tempfile::tempdir().unwrap();
    let mut compared = 0;
    for case in fixture["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let models = build(root, case);
        let mountinfo = info.path().join(format!("{id}-mountinfo"));
        if let Some(lines) = case["mountinfo"].as_array() {
            let text: Vec<String> = lines
                .iter()
                .map(|l| {
                    l.as_str()
                        .unwrap()
                        .replace("@MODELS@", models.to_str().unwrap())
                })
                .collect();
            std::fs::write(&mountinfo, text.join("\n") + "\n").unwrap();
        }
        for name in case["readonly"].as_array().into_iter().flatten() {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(
                models.join(name.as_str().unwrap()),
                std::fs::Permissions::from_mode(0o555),
            )
            .unwrap();
        }
        let docker = Arc::new(FakeDocker {
            spec: case["docker"].clone(),
            lists: AtomicUsize::new(0),
        });
        let delete = ModelDelete::new(config(&models, &mountinfo, case), docker.clone());
        let state = state(Some(delete), docker.clone(), "http://127.0.0.1:9");
        for (step, (request, expected)) in case["requests"]
            .as_array()
            .unwrap()
            .iter()
            .zip(case["results"].as_array().unwrap())
            .enumerate()
        {
            docker.lists.store(0, Ordering::SeqCst);
            let (status, kind, body) = post(
                state.clone(),
                request["body"].as_str().unwrap(),
                request["content_type"].as_str(),
                true,
            )
            .await;
            let body = body.replace(root.to_str().unwrap(), "@ROOT@");
            let ctx = format!("{id} step {step}: {}", request["body"]);
            assert_eq!(
                u64::from(status),
                expected["status"].as_u64().unwrap(),
                "{ctx}: {body}"
            );
            assert_eq!(kind.as_deref(), expected["content_type"].as_str(), "{ctx}");
            assert_eq!(body, expected["body"].as_str().unwrap(), "{ctx}");
            assert_eq!(tree(root), expected["tree"], "{ctx}");
            assert_eq!(
                docker.lists.load(Ordering::SeqCst) as u64,
                expected["docker_lists"].as_u64().unwrap(),
                "{ctx}"
            );
            compared += 1;
        }
        for name in case["readonly"].as_array().into_iter().flatten() {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(
                models.join(name.as_str().unwrap()),
                std::fs::Permissions::from_mode(0o755),
            )
            .unwrap();
        }
    }
    assert!(compared >= 60, "{compared}");
}

/// noevia#1966: native downloads with a Python delete. Python cannot see the native jobs, so any
/// queued or running download refuses the delete before it is forwarded; with none it forwards.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn python_delete_is_refused_while_a_native_download_is_active() {
    use noevia_model_manager::downloads::{Config as DlConfig, Downloads, Planned, Queued};
    let dir = tempfile::tempdir().unwrap();
    let models = synthetic_tree(dir.path());
    let data = dir.path().join("data");
    std::fs::create_dir(&data).unwrap();
    let table = Downloads::new(DlConfig::production(
        models.to_str().unwrap().to_owned(),
        data.to_str().unwrap(),
        1,
    ))
    .unwrap();
    // The forwarded request goes to a child that never exists (a closed port).
    let closed = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let child = format!("http://127.0.0.1:{}", closed.local_addr().unwrap().port());
    drop(closed);
    let docker = Arc::new(FakeDocker {
        spec: Value::Null,
        lists: AtomicUsize::new(0),
    });
    let mut data_state = Arc::try_unwrap(state(None, docker, &child)).ok().unwrap();
    data_state.downloads = Some(table.clone());
    let shared = Arc::new(data_state);
    let body = r#"{"models":["sub/s.gguf"]}"#;

    let (status, _, idle) = post(shared.clone(), body, Some("application/json"), true).await;
    assert_ne!(status, 409, "no active download: forwarded ({idle})");

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let server = tokio::spawn(async move {
        let mut held = Vec::new();
        while let Ok((sock, _)) = listener.accept().await {
            held.push(sock);
        }
    });
    let queued = table.queue(vec![Planned {
        repo_id: "example.test".into(),
        filename: "elsewhere/b.gguf".into(),
        url: format!("http://127.0.0.1:{port}/b.gguf"),
        total_bytes: 0,
    }]);
    assert_eq!(queued, Queued::Done);
    let (status, _, text) = post(shared, body, Some("application/json"), true).await;
    assert_eq!(status, 409, "{text}");
    assert_eq!(
        serde_json::from_str::<Value>(&text).unwrap()["detail"],
        noevia_model_manager::PYTHON_DELETE_WHILE_DOWNLOADING
    );
    assert!(models.join("sub/s.gguf").exists());
    server.abort();
}
